package tw.rex.parentcontrol;
import android.content.SharedPreferences;import java.lang.reflect.*;import java.util.*;import java.net.*;import org.json.*;import tw.rex.link.*;
public class MultiParentTest {
 static int checks;static void ok(boolean b,String why){if(!b)throw new AssertionError(why);checks++;System.out.println("PASS "+why);}
 static SharedPreferences prefs(){Map<String,Object> values=new HashMap<>();InvocationHandler handler=(proxy,method,args)->{String name=method.getName();if(name.equals("getString"))return values.containsKey(args[0])?values.get(args[0]):args[1];if(name.equals("edit")){return java.lang.reflect.Proxy.newProxyInstance(MultiParentTest.class.getClassLoader(),new Class[]{SharedPreferences.Editor.class},(ep,em,ea)->{if(em.getName().equals("putString")){values.put((String)ea[0],ea[1]);return ep;}if(em.getName().equals("commit"))return true;return null;});}return null;};return (SharedPreferences)java.lang.reflect.Proxy.newProxyInstance(MultiParentTest.class.getClassLoader(),new Class[]{SharedPreferences.class},handler);}
 static JSONObject poll(ParentService service,String key,String ack,String nonce)throws Exception{return Crypto.open(key,service.handle(new JSONObject().put("id","tv-test").put("type","poll").put("data",Crypto.seal(key,new JSONObject().put("name","Test TV").put("nonce",nonce).put("ack",ack).put("status",new JSONObject())))).getString("data"));}
 public static void main(String[] args)throws Exception{
 ParentService.devices.clear();ParentService a=new ParentService(),b=new ParentService();a.p=prefs();b.p=prefs();a.phoneId="parent-a";b.phoneId="parent-b";String ka=Crypto.token(),kb=Crypto.token();a.p.edit().putString("secret.tv-test",ka).commit();b.p.edit().putString("secret.tv-test",kb).commit();
 JSONObject hello=new JSONObject().put("id","tv-test").put("type","hello").put("name","TV").put("pub","test-public");ok(a.handle(hello).getString("phoneId").equals("parent-a"),"first phone identity");ok(b.handle(hello).getString("phoneId").equals("parent-b"),"second phone identity");
 ok(poll(a,ka,"","nonce-a").getString("nonce").equals("nonce-a"),"first phone authenticated");ok(poll(b,kb,"","nonce-b").getString("nonce").equals("nonce-b"),"second phone authenticated independently");
 try{poll(a,kb,"","wrong");throw new AssertionError();}catch(Exception expected){ok(expected.getMessage().equals("not paired"),"other parent key cannot authenticate this phone");}
 // Real separate services have independent static maps in separate processes. Separate the per-process device maps in this host test.
 ParentService.devices.clear();a.handle(hello);poll(a,ka,"","a");a.command("tv-test","lock",new JSONObject());JSONObject first=poll(a,ka,"","a2");String cid=first.getJSONObject("command").getString("id");ok(poll(a,ka,"","a3").getJSONObject("command").getString("id").equals(cid),"unacknowledged command retried");ok(poll(a,ka,"unrelated-parent-ack","a4").has("command"),"another parent's acknowledgment cannot drop command");ok(!poll(a,ka,cid,"a5").has("command"),"matching acknowledgment removes command");
 a.command("tv-test","add_parent",new JSONObject());ok(poll(a,ka,"","a6").getJSONObject("command").getString("action").equals("add_parent"),"authenticated add-parent command delivered");
 InetAddress local=null;for(InetAddress dest:LanDiscovery.broadcasts())ok(dest instanceof Inet4Address,"broadcast destination IPv4");Enumeration<NetworkInterface> all=NetworkInterface.getNetworkInterfaces();while(all.hasMoreElements()){Enumeration<InetAddress> addresses=all.nextElement().getInetAddresses();while(addresses.hasMoreElements()){InetAddress ip=addresses.nextElement();if(LanDiscovery.privateV4(ip))local=ip;}}
 ok(!LanDiscovery.privateV4(InetAddress.getByName("8.8.8.8")),"public discovery source rejected");ok(!LanDiscovery.privateV4(InetAddress.getByName("127.0.0.1")),"loopback discovery source rejected");
 if(local==null){System.out.println("SKIP actual private-LAN response: sandbox has no private IPv4 interface");System.out.println(checks+" checks passed");return;}a.server=new ServerSocket(0);a.running=true;Thread responder=new Thread(()->a.beaconLoop());responder.start();long end=System.currentTimeMillis()+1000;while(a.beacon==null&&System.currentTimeMillis()<end)Thread.yield();
 try(DatagramSocket client=new DatagramSocket(new InetSocketAddress(local,0))){client.setSoTimeout(1500);String nonce=UUID.randomUUID().toString();byte[] bytes=new JSONObject().put("type","learning-find-v1").put("nonce",nonce).toString().getBytes("UTF-8");client.send(new DatagramPacket(bytes,bytes.length,local,LanDiscovery.PORT));DatagramPacket reply=new DatagramPacket(new byte[2048],2048);client.receive(reply);JSONObject result=new JSONObject(new String(reply.getData(),0,reply.getLength(),"UTF-8"));ok(nonce.equals(result.getString("nonce")),"real UDP discovery echoes probe nonce");ok(result.getInt("port")==a.server.getLocalPort(),"discovery advertises actual TCP port");ok(result.getString("phoneId").equals("parent-a"),"discovery advertises phone identity without secrets");}finally{a.running=false;a.beacon.close();a.server.close();responder.join(2000);a.pool.shutdownNow();b.pool.shutdownNow();}
 System.out.println(checks+" checks passed");
 }
}
